// Разбор вложений: выбираем PDF-расчёт под ключ `calc`, прочее — в доп-контекст.
const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin);
const nameOf = (k) => (bin[k].fileName || k);
const lower = (k) => nameOf(k).toLowerCase();
const isPdf = (k) => (bin[k].mimeType||'').includes('pdf') || lower(k).endsWith('.pdf');
// исключаем явно не-расчёты по имени файла
const EXCLUDE = ['пени','платеж','платёж','поручени','пояснительн','реестр','показан'];
const pdfs = keys.filter(isPdf);
const candidates = pdfs.filter(k => !EXCLUDE.some(w => lower(k).includes(w)));
// предпочитаем «расчёт задолженности»; иначе первый не-исключённый PDF
const preferred = candidates.find(k => lower(k).includes('расч') && lower(k).includes('задолж'));
const calcKey = preferred || candidates[0] || null;
// выбранный расчёт кладём под стабильный ключ `calc` (его пишет на диск Write Calc PDF)
const outBin = {};
let calc_name = null;
if (calcKey) { outBin.calc = bin[calcKey]; calc_name = nameOf(calcKey); }
const extras = keys.filter(k => k !== calcKey).map(nameOf);
const j = item.json;
return [{ json: {
  has_calc: !!calcKey,
  calc_name,
  dop_context: (j.text || j.textPlain || '') + (extras.length ? ('\n[вложения: ' + extras.join(', ') + ']') : ''),
  subject: j.subject || '',
  from: (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || (typeof j.from === 'string' ? j.from : ''),
  messageId: j.messageId || (j.headers && j.headers['message-id']) || '',
  retry: 0
}, binary: outBin }];

// Склейка системных промптов из ответов HTTP-узлов. Сеть НЕ трогаем: helpers.httpRequest
// в Code-узле виснет в task-runner n8n, поэтому контракты качают отдельные HTTP Request-узлы.
const sep = '\n\n---\n\n';
const j = $('Prepare Inputs').first().json;
j.extraction_system = $('Fetch Extraction').first().json.data + sep + $('Fetch Schema').first().json.data;
j.generation_system = $('Fetch Spec').first().json.data + sep + $('Fetch Generation').first().json.data + sep + '# Шаблон сборки (болванки дословно, шаблоны блоков)\n' + $('Fetch Template').first().json.data;
return [{ json: j, binary: $('Prepare Inputs').first().binary }];

