parameters.text:
=Сгенерируй пояснительную записку по структуре и в соответствии с контрактом (в system) из данных манифеста ниже. Верни ТОЛЬКО JSON: {"html": "<записка в HTML>", "executor_notes": ["..."]}.

Манифест:
{{ JSON.stringify($json.manifest) }}

parameters.jsCode:
const resp = $input.first().json;
let text = typeof resp.text === 'string' ? resp.text : (resp.content || []).map(c => c.type === 'text' ? c.text : '').join('\n');
text = text.replace(/```json|```/g, '').trim();
let out; try { out = JSON.parse(text); } catch(e){ out = { html: '<p>Ошибка разбора ответа генератора.</p><pre>'+text+'</pre>', executor_notes: ['Проверьте ответ агента генерации'] }; }
// from/subject/messageId берём из Parse Manifest (в выходе модели их нет)
const carry = $('Parse Manifest').first().json;
const notes = (out.executor_notes && out.executor_notes.length) ? ('Требует внимания:\n- ' + out.executor_notes.join('\n- ')) : 'Замечаний нет.';
// записка -> бинарный HTML-файл (по умолчанию вложение; при конвертере станет DOCX)
const b64 = Buffer.from(out.html || '', 'utf8').toString('base64');
return [{ json: { executor_notes: notes, from: carry.from, subject: carry.subject, messageId: carry.messageId },
  binary: { zapiska: { data: b64, mimeType: 'text/html', fileName: 'poyasnitelnaya_zapiska.html' } } }];

const b = $input.first().binary.data;
b.fileName = 'node-' + $execution.id + '.docx';
b.mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const j = $('Parse Output').first().json;
return [{ json: j, binary: { zapiska: b } }];
